import { useId } from 'react';
import { useForm } from '@tanstack/react-form';

import { FieldRenderer } from '@/components/formedible/field-renderer';
import { Form as FormRoot } from '@/components/formedible/form';
import type { FormProps } from '@/components/formedible/form';
import { normalizeFieldConfig } from '@/lib/formedible/normalize-field-config';
import type { UseFormedibleOptions } from '@/lib/formedible/types';

export function useFormedible<TFormValues extends Record<string, string> = Record<string, string>>(config: UseFormedibleOptions<TFormValues>) {
  const formId = useId();
  const fields = config.fields.map((field) => normalizeFieldConfig(field));
  const form = useForm({
    defaultValues: config.formOptions.defaultValues,
    onSubmit: async ({ value }) => {
      await config.formOptions.onSubmit?.({ value });
    },
  });

  function Form({ className, ...props }: FormProps) {
    return (
      <FormRoot
        className={className}
        onSubmit={(event) => {
          event.preventDefault();
          event.stopPropagation();
          form.handleSubmit();
        }}
        {...props}
      >
        {fields.map((fieldConfig) => (
          <form.Field key={fieldConfig.name} name={fieldConfig.name}>
            {(field) => {
              const value = typeof field.state.value === 'string' ? field.state.value : '';
              const error = field.state.meta.errors.map((item) => String(item)).at(0);
              type FieldValueUpdate = Parameters<typeof field.handleChange>[0];

              return (
                <FieldRenderer
                  fieldConfig={fieldConfig}
                  field={{
                    id: `${formId}-${fieldConfig.name}`,
                    name: fieldConfig.name,
                    value,
                    error,
                    onBlur: field.handleBlur,
                    onChange: (nextValue) => field.handleChange(nextValue as FieldValueUpdate),
                  }}
                />
              );
            }}
          </form.Field>
        ))}
      </FormRoot>
    );
  }

  return { Form, form };
}

import type { ComponentProps } from 'react';

import { cn } from '@/lib/utils';

export type FormProps = ComponentProps<'form'>;

export function Form({ className, ...props }: FormProps) {
  return <form className={cn(className)} {...props} />;
}

import type { FormedibleFieldRenderProps } from '@/lib/formedible/types';

import { getFieldComponent } from './fields/field-registry';

export function FieldRenderer<TFormValues extends Record<string, string>>(props: FormedibleFieldRenderProps<TFormValues>) {
  const FieldComponent = getFieldComponent<TFormValues>(props.fieldConfig.type);

  return <FieldComponent fieldConfig={props.fieldConfig} field={props.field} />;
}

import type { ReactNode } from 'react';

import { Field, FieldDescription, FieldError, FieldLabel } from '@/components/ui/field';
import type { FormedibleTextController, NormalizedFieldConfig } from '@/lib/formedible/types';

export interface FieldWrapperProps<TFormValues extends Record<string, string> = Record<string, string>> {
  readonly fieldConfig: NormalizedFieldConfig<TFormValues>;
  readonly field: FormedibleTextController;
  readonly children: ReactNode;
}

export function FieldWrapper<TFormValues extends Record<string, string>>({ fieldConfig, field, children }: FieldWrapperProps<TFormValues>) {
  return (
    <Field className={fieldConfig.className} data-disabled={fieldConfig.disabled ? 'true' : undefined}>
      {fieldConfig.label ? (
        <FieldLabel htmlFor={field.id}>
          {fieldConfig.label}
          {fieldConfig.required ? <span aria-hidden="true"> *</span> : undefined}
        </FieldLabel>
      ) : undefined}
      {children}
      {fieldConfig.description ? <FieldDescription>{fieldConfig.description}</FieldDescription> : undefined}
      {field.error ? <FieldError>{field.error}</FieldError> : undefined}
    </Field>
  );
}

import { Input as TextInput } from '@/components/ui/input';
import type { FormedibleFieldRenderProps } from '@/lib/formedible/types';

import { FieldWrapper } from './field-wrapper';

export function TextField<TFormValues extends Record<string, string>>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <TextInput
        id={field.id}
        name={field.name}
        type={fieldConfig.type}
        value={field.value}
        placeholder={fieldConfig.placeholder}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onChange={(event) => field.onChange(event.target.value)}
      />
    </FieldWrapper>
  );
}

import type { ReactNode } from 'react';

import type { FormedibleFieldRenderProps, FormedibleFieldType } from '@/lib/formedible/types';

import { TextField } from './text-field';

const fieldRegistry = {
  text: TextField,
} satisfies Record<FormedibleFieldType, typeof TextField>;

export function getFieldComponent<TFormValues extends Record<string, string>>(
  type: FormedibleFieldType,
): (props: FormedibleFieldRenderProps<TFormValues>) => ReactNode {
  return fieldRegistry[type];
}

